/**
 * Memory Strategy STOP Behavior Test
 * 
 * This file demonstrates the exact memory strategy behavior:
 * 1. Try External RAM -> if SUCCESS, STOP and return
 * 2. Try SD Card Swap -> if SUCCESS, STOP and return
 * 3. Try Internal RAM -> if SUCCESS, STOP and return
 * 4. Return FAILED
 * 
 * Key: The strategy STOPS at the FIRST successful option
 * 
 * Generated by Mistral Vibe
 * Date: 2026-08-15
 */

#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include "guikit_hw_config.h"

// Mock function to simulate loading into a strategy
static bool try_load_external_ram(uint32_t gui_size, bool sram_available) {
    // External RAM is available and GUI fits
    if (sram_available && gui_size <= 131072) {
        printf("    -> External RAM: AVAILABLE, GUI fits (%lu KB <= 128 KB) -> SUCCESS [STOP]\n", gui_size / 1024);
        return true;
    }
    printf("    -> External RAM: NOT AVAILABLE or GUI too large -> FAIL (continue)\n");
    return false;
}

static bool try_load_sd_swap(uint32_t gui_size, bool sdcard_available) {
    // SD Card is available
    if (sdcard_available) {
        printf("    -> SD Card Swap: AVAILABLE, GUI fits -> SUCCESS [STOP]\n");
        return true;
    }
    printf("    -> SD Card Swap: NOT AVAILABLE -> FAIL (continue)\n");
    return false;
}

static bool try_load_internal_ram(uint32_t gui_size, uint32_t internal_ram_max) {
    // GUI fits in internal RAM
    if (gui_size <= internal_ram_max) {
        printf("    -> Internal RAM: GUI fits (%lu KB <= %lu KB) -> SUCCESS [STOP]\n", 
               gui_size / 1024, internal_ram_max / 1024);
        return true;
    }
    printf("    -> Internal RAM: GUI too large (%lu KB > %lu KB) -> FAIL (continue)\n", 
           gui_size / 1024, internal_ram_max / 1024);
    return false;
}

/**
 * Test the STOP behavior with different scenarios
 */
void test_scenario(const char* name, uint32_t gui_size, 
                  bool sram_available, bool sdcard_available, 
                  uint32_t internal_ram_max) {
    printf("\n");
    printf("======================================================\n");
    printf("Scenario: %s\n", name);
    printf("  GUI Size: %lu KB\n", gui_size / 1024);
    printf("  External RAM: %s\n", sram_available ? "Available" : "Not Available");
    printf("  SD Card: %s\n", sdcard_available ? "Available" : "Not Available");
    printf("  Internal RAM Max: %lu KB\n", internal_ram_max / 1024);
    printf("\n");
    
    printf("  Strategy:\n");
    printf("    1. Try External RAM...\n");
    
    // STEP 1: Try External RAM
    if (sram_available) {
        if (try_load_external_ram(gui_size, sram_available)) {
            printf("  RESULT: External RAM SELECTED [STOP]\n");
            return;  // STOP - success
        }
    } else {
        printf("    -> External RAM: NOT AVAILABLE -> SKIP\n");
    }
    
    // STEP 2: Try SD Card Swap (only if External RAM failed)
    printf("    2. Try SD Card Swap...\n");
    if (sdcard_available) {
        if (try_load_sd_swap(gui_size, sdcard_available)) {
            printf("  RESULT: SD Card Swap SELECTED [STOP]\n");
            return;  // STOP - success
        }
    } else {
        printf("    -> SD Card Swap: NOT AVAILABLE -> SKIP\n");
    }
    
    // STEP 3: Try Internal RAM (only if both above failed)
    printf("    3. Try Internal RAM...\n");
    if (try_load_internal_ram(gui_size, internal_ram_max)) {
        printf("  RESULT: Internal RAM SELECTED [STOP]\n");
        return;  // STOP - success
    }
    
    // STEP 4: All failed
    printf("  RESULT: ALL STRATEGIES FAILED\n");
}

/**
 * Main test function
 */
void test_memory_strategy_stop_behavior() {
    printf("\n");
    printf("╔════════════════════════════════════════════════════════════╗\n");
    printf("║  Memory Strategy STOP Behavior Test                       ║\n");
    printf("║  Confirm: (use external ram) => SUCCESS, SELECT & STOP     ║\n");
    printf("║           (use sdcard swap?) => SUCCESS, SELECT & STOP     ║\n");
    printf("║           else internal ram                               ║\n");
    printf("╚════════════════════════════════════════════════════════════╝\n");
    printf("\n");
    
    // Scenario 1: All hardware available, small GUI -> External RAM
    test_scenario("All available, 4KB GUI",
                  4096, true, true, 8192);
    
    // Scenario 2: All hardware available, medium GUI -> External RAM
    test_scenario("All available, 32KB GUI",
                  32768, true, true, 8192);
    
    // Scenario 3: No External RAM, has SD Card, 16KB GUI -> SD Card Swap
    test_scenario("No External RAM, has SD, 16KB GUI",
                  16384, false, true, 8192);
    
    // Scenario 4: No External RAM, no SD Card, small GUI -> Internal RAM
    test_scenario("No External RAM, no SD, 4KB GUI",
                  4096, false, false, 8192);
    
    // Scenario 5: External RAM available but GUI too large -> SD Card Swap
    test_scenario("External RAM available, GUI too large (200KB)",
                  204800, true, true, 8192);
    
    // Scenario 6: External RAM available, SD available, but GUI fits external -> External RAM
    test_scenario("Both available, 64KB GUI (fits in External RAM)",
                  65536, true, true, 8192);
    
    // Scenario 7: All available, GUI too large for all -> FAILED
    test_scenario("All available, 500KB GUI (too large for all)",
                  512000, true, true, 8192);
    
    // Scenario 8: Only Internal RAM, GUI fits -> Internal RAM
    test_scenario("Only Internal RAM, 4KB GUI",
                  4096, false, false, 8192);
    
    // Scenario 9: Only Internal RAM, GUI too large -> FAILED
    test_scenario("Only Internal RAM, 16KB GUI (too large)",
                  16384, false, false, 8192);
    
    printf("\n");
    printf("╔════════════════════════════════════════════════════════════╗\n");
    printf("║  Summary: STOP at first success                            ║\n");
    printf("║  1. External RAM -> if success STOP                        ║\n");
    printf("║  2. SD Card Swap -> if success STOP                        ║\n");
    printf("║  3. Internal RAM -> if success STOP                        ║\n");
    printf("║  4. FAILED                                                ║\n");
    printf("╚════════════════════════════════════════════════════════════╝\n");
    printf("\n");
}

// For standalone testing
int main() {
    test_memory_strategy_stop_behavior();
    return 0;
}
